<template>
  <FmStatePanel v-if="!session.ready" state="loading" title="正在打开工作台"/>
  <RouterView v-else-if="isPublicPage||isAdminPage"/>
  <div v-else-if="!session.user" class="auth">
    <section class="auth-copy"><div class="brand-mark">R</div><span class="fm-kicker">{{session.config.site_name}} · 倍率防护</span><h1>上游调价后，<br/>你的利润仍然可控。</h1><p>使用普通 API Key 关注 New API 与 Sub2API 的实际倍率，并按你的规则安全同步到自有站点。</p><ul><li>上游倍率发生变化时及时处理</li><li>生图价格可从真实使用记录中观测</li><li>异常、修改和失败原因清楚留档</li></ul></section>
    <form class="auth-form fm-card" @submit.prevent="submit"><span class="fm-kicker">{{forgot?'找回密码':registering?'创建账户':'欢迎回来'}}</span><h2>{{forgot?'找回密码':registering?'注册并开始使用':'登录工作台'}}</h2>
      <label class="field"><span>{{registering||forgot?'邮箱':'账号或邮箱'}}</span><input v-model.trim="auth.email" :type="registering||forgot?'email':'text'" autocomplete="email" required/></label>
      <label v-if="!forgot" class="field"><span>密码</span><input v-model="auth.password" type="password" :autocomplete="registering?'new-password':'current-password'" minlength="6" required/></label>
      <div v-if="error" class="notice error">{{error}}</div><div v-if="authMessage" class="notice ok">{{authMessage}}</div>
      <FmButton variant="primary" type="submit" :loading="busy">{{forgot?'发送重置邮件':registering?'注册并进入':'登录'}}</FmButton>
      <button v-if="!registering&&!forgot" class="switch" type="button" @click="forgot=true;error=''">忘记密码？</button>
      <button v-if="forgot||registering||session.config.registration_open" class="switch" type="button" @click="toggleAuth">{{forgot?'返回登录':registering?'已有账号？返回登录':'没有账号？注册'}}</button>
    </form>
  </div>
  <div v-else class="shell"><header class="mobile-head"><button aria-label="打开导航" @click="menu=true"><Menu :size="18" aria-hidden="true"/></button><strong>{{session.config.site_name}}</strong></header><button v-if="menu" class="backdrop" aria-label="关闭导航" @click="menu=false"/>
    <aside :class="{open:menu}"><div class="brand"><span>R</span><div>{{session.config.site_name}}<small>倍率同步平台</small></div></div><nav @click="menu=false"><RouterLink v-for="item in navigation" :key="item.to" :to="item.to"><component :is="item.icon" :size="17" :stroke-width="1.8" aria-hidden="true"/><span>{{item.label}}</span></RouterLink></nav>
      <div class="sidebar-bottom"><div class="theme-quick segmented" aria-label="界面主题"><button v-for="item in themes" :key="item.value" :class="{active:theme===item.value}" :title="item.label" :aria-label="item.label" @click="chooseTheme(item.value)"><component :is="item.icon" :size="14" :stroke-width="1.8" aria-hidden="true"/><span>{{item.short}}</span></button></div><div class="profile"><span>{{session.user.email}}</span><button @click="doLogout"><LogOut :size="14" aria-hidden="true"/>退出登录</button></div></div>
    </aside><main><RouterView/></main><OnboardingGuide v-if="!session.user.onboarded" @done="onboardingDone"/>
  </div>
  <div class="toast-stack" aria-live="polite"><article v-for="t in session.toasts" :key="t.id" class="toast" :class="t.type"><button class="toast-close" aria-label="关闭" @click="dismissToast(t.id)">×</button><strong v-if="t.title" class="toast-title">{{t.title}}</strong><div>{{t.message}}</div><div v-if="t.site_name||t.source_name||t.group_name" class="toast-context">{{[t.site_name,t.source_name,t.group_name].filter(Boolean).join(' / ')}}</div></article></div>
</template>
<script setup>
import{computed,onBeforeUnmount,onMounted,reactive,ref}from"vue";import{useRoute,useRouter}from"vue-router";import{BellRing,CircleUserRound,Info,LayoutDashboard,LogOut,Mail,Menu,MonitorCog,Moon,RadioTower,RefreshCw,ServerCog,Sun}from"@lucide/vue";import{api,bootstrap,dismissToast,logout,openEvents,saveSession,session,toast}from"./api/client.js";import{readThemeMode,setThemeMode}from"./ui/freemodel/theme.js";import FmButton from"./ui/freemodel/components/FmButton.vue";import FmStatePanel from"./ui/freemodel/components/FmStatePanel.vue";import OnboardingGuide from"./components/OnboardingGuide.vue";
const router=useRouter(),route=useRoute(),registering=ref(false),forgot=ref(false),busy=ref(false),error=ref(""),authMessage=ref(""),menu=ref(false),theme=ref(readThemeMode()),auth=reactive({email:"",password:""}),navigation=[{to:"/",label:"概览",icon:LayoutDashboard},{to:"/sites",label:"我的站点",icon:ServerCog},{to:"/sources",label:"上游管理",icon:RadioTower},{to:"/tasks",label:"同步任务",icon:RefreshCw},{to:"/events",label:"异常与变更",icon:BellRing},{to:"/settings",label:"通知设置",icon:Mail},{to:"/profile",label:"个人信息",icon:CircleUserRound},{to:"/about",label:"关于",icon:Info}],themes=[{value:"system",icon:MonitorCog,short:"自动",label:"跟随电脑"},{value:"light",icon:Sun,short:"亮色",label:"亮色"},{value:"dark",icon:Moon,short:"暗色",label:"暗色"}];let es;const isPublicPage=computed(()=>route.path==="/reset-password"),isAdminPage=computed(()=>route.path===`/${session.config.admin_path}`);onMounted(async()=>{await bootstrap();if(session.user)es=openEvents()});onBeforeUnmount(()=>es?.close());
function toggleAuth(){if(forgot.value){forgot.value=false;registering.value=false}else registering.value=!registering.value;error.value="";authMessage.value=""}
async function submit(){busy.value=true;error.value="";authMessage.value="";try{if(forgot.value){const data=await api("/api/auth/forgot",{method:"POST",body:JSON.stringify({email:auth.email})});authMessage.value=data.message;toast(data.message,"success");return}const isRegister=registering.value,data=await api(`/api/auth/${isRegister?'register':'login'}`,{method:"POST",body:JSON.stringify(auth)});saveSession(data);es=openEvents();toast(isRegister?"注册成功，欢迎使用":"登录成功","success");router.push("/")}catch(e){error.value=e.message;toast(e.message,"error")}finally{busy.value=false}}
function chooseTheme(value){theme.value=value;setThemeMode(value)}function onboardingDone(){session.user.onboarded=true;toast("首次引导已完成","success")}function doLogout(){es?.close();auth.email="";auth.password="";registering.value=false;forgot.value=false;logout();toast("已安全退出");router.push("/")}
</script>
<style scoped>.auth{min-height:100vh;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(360px,.85fr);align-items:center;gap:8vw;max-width:1160px;margin:auto;padding:48px}.auth-copy h1{margin:20px 0 16px;font-size:clamp(38px,5vw,62px);line-height:1.05;letter-spacing:-.045em}.auth-copy p{max-width:590px;color:var(--fm-ink-soft);font-size:17px;line-height:1.65}.auth-copy ul{display:grid;gap:9px;padding:0;list-style:none;color:var(--fm-ink-soft)}.auth-copy li::before{content:"✓";margin-right:9px;color:var(--fm-accent)}.brand-mark{display:grid;place-items:center;width:42px;height:42px;margin-bottom:20px;border-radius:11px;background:var(--fm-ink);color:var(--fm-bg);font-weight:800}.auth-form{padding:32px}.auth-form h2{margin:6px 0 24px;font-size:24px}.auth-form>.button{width:100%}.switch{width:100%;margin-top:12px;background:transparent;color:var(--fm-ink-muted);font-size:12px}.shell{min-height:100vh}.shell aside{position:fixed;inset:0 auto 0 0;z-index:40;display:flex;flex-direction:column;width:240px;padding:24px 16px 18px;border-right:1px solid var(--fm-line-soft);background:color-mix(in srgb,var(--fm-bg) 96%,transparent);backdrop-filter:blur(12px)}.brand{display:flex;align-items:center;gap:11px;padding:0 10px 24px;font-size:17px;font-weight:700}.brand>span{display:grid;place-items:center;width:31px;height:31px;border-radius:8px;background:var(--fm-ink);color:var(--fm-bg)}.brand small{display:block;color:var(--fm-ink-muted);font-size:10px;font-weight:500}.shell nav{display:grid;gap:2px}.shell nav a{display:flex;align-items:center;gap:10px;min-height:38px;padding:9px 11px;border-radius:8px;color:var(--fm-ink-soft);font-size:13px}.shell nav a svg{flex:0 0 auto;opacity:.72;transition:opacity .14s,transform .14s}.shell nav a:hover{background:var(--fm-bg-warm)}.shell nav a:hover svg{opacity:1;transform:translateX(1px)}.shell nav .router-link-active{background:var(--fm-bg-card);color:var(--fm-ink);box-shadow:var(--fm-card-shadow);font-weight:600}.shell nav .router-link-active svg{opacity:1}.sidebar-bottom{display:grid;gap:10px;margin-top:auto}.theme-quick button{display:grid;flex:1;justify-items:center;gap:3px;padding:6px 3px}.theme-quick button span{display:block;font-size:9px}.profile{display:grid;gap:7px;padding:13px 10px 0;border-top:1px solid var(--fm-line-soft);font-size:11px;overflow-wrap:anywhere}.profile button{display:flex;align-items:center;gap:7px;padding:0;background:transparent;color:var(--fm-ink-muted);text-align:left}.shell main{width:calc(100% - 240px);margin-left:240px}.mobile-head,.backdrop{display:none}.toast.error{color:var(--fm-error)}.toast.warning{color:var(--fm-warn)}.toast.success{color:var(--fm-ok)}@media(max-width:820px){.auth{grid-template-columns:1fr;padding:24px 20px}.auth-copy{display:none}.shell aside{width:min(280px,calc(100vw - 48px));transform:translateX(-102%);transition:transform .22s}.shell aside.open{transform:none}.shell main{width:100%;margin:0}.mobile-head{position:sticky;top:0;z-index:35;display:flex;align-items:center;gap:12px;height:52px;padding:0 20px;border-bottom:1px solid var(--fm-line);background:var(--fm-bg)}.mobile-head button{display:grid;place-items:center;width:36px;height:36px;border-radius:8px;background:var(--fm-bg-warm)}.backdrop{position:fixed;inset:0;z-index:38;display:block;width:100%;background:rgba(0,0,0,.3)}}@media(max-width:480px){.auth{padding:14px}.auth-form{padding:22px}.mobile-head{padding:0 14px}}</style>
